<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>The Great Wave off Kanagawa — low poly</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#e8ddc0}
  #c{display:block;width:100%;height:100%}
  #cap{position:fixed;left:14px;bottom:10px;font:12px/1.4 Georgia,serif;color:#3a3a3a;opacity:.75;pointer-events:none}
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="cap">Kanagawa oki nami ura (1831) — low poly reinterpretation</div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

/* ---- palette sampled from the print ---- */
const COL = {
  sky:      0xefe4c8,   // cream sky
  deep:     0x14304d,   // darkest Prussian blue
  mid:      0x1e4c78,   // main wave body
  light:    0x55809f,   // pale blue
  foam:     0xf3eee1,   // off-white foam
  hull:     0xc08040,   // boat hull ochre
  hullLt:   0xe6c69a,
  hullDk:   0x7a4e28,
  fuji:     0x2c405e,   // mountain body
  snow:     0xf1eee5,
  ink:      0x262626
};

const renderer = new THREE.WebGLRenderer({canvas:document.getElementById('c'),antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
function resize(){renderer.setSize(innerWidth,innerHeight);}
addEventListener('resize',resize);resize();

const scene = new THREE.Scene();
scene.background = new THREE.Color(COL.sky);
scene.fog = new THREE.Fog(0xdccfae, 70, 170);

const camera = new THREE.PerspectiveCamera(40, innerWidth/innerHeight, 0.1, 400);
camera.position.set(0, 10, 52);
camera.lookAt(0, 6, 0);

scene.add(new THREE.HemisphereLight(0xfff4dc, 0x1e4c78, 1.05));
const sun = new THREE.DirectionalLight(0xfff0d0, 0.65);
sun.position.set(-15, 35, 25);
scene.add(sun);

const flat = c => new THREE.MeshLambertMaterial({color:c,flatShading:true});

/* =========================================================
   MOUNT FUJI
   ========================================================= */
{
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.ConeGeometry(15, 13, 7, 1), flat(COL.fuji));
  body.position.y = 6.5; g.add(body);
  const cap  = new THREE.Mesh(new THREE.ConeGeometry(5.6, 5.0, 7, 1), flat(COL.snow));
  cap.position.y = 10.8; g.add(cap);
  g.position.set(10, -5, -52);
  scene.add(g);
}

/* =========================================================
   WAVES — extruded swells.
   Each swell is a long bar (BoxGeometry) whose top edge is
   displaced into a sine profile, giving a rolling blue mass
   with a white foam lip on the crest.
   ========================================================= */
const swells = [];   // {mesh, foam, phase, baseY}

function swell(z, y, h, w, color, phase){
  const segs = 40, depth = 4.5;
  const geo = new THREE.BoxGeometry(w, h, depth, segs, 1, 1);
  const p = geo.attributes.position;
  for(let i=0;i<p.count;i++){
    const x = p.getX(i), yy = p.getY(i);
    if(yy > 0){ // top edge -> sine profile
      const t = (x + w/2)/w;
      const crest = Math.sin(t*Math.PI*3 + phase)*0.5 + 0.5; // 0..1
      p.setY(i, yy + crest*h*0.55);
      // slight forward lean on the crest
      p.setZ(i, p.getZ(i) + crest*0.8);
    }
  }
  p.needsUpdate = true; geo.computeVertexNormals();
  const m = new THREE.Mesh(geo, flat(color));
  m.position.set(0, y, z);
  scene.add(m);

  // foam lip: thin white box along the crest
  const fg = new THREE.BoxGeometry(w, 0.7, depth*0.6, segs, 1, 1);
  const fp = fg.attributes.position;
  for(let i=0;i<fp.count;i++){
    const x = fp.getX(i), yy = fp.getY(i);
    const t = (x + w/2)/w;
    const crest = Math.sin(t*Math.PI*3 + phase)*0.5 + 0.5;
    if(yy>0) fp.setY(i, yy + crest*h*0.55 + 2.0);
  }
  fp.needsUpdate = true; fg.computeVertexNormals();
  const fm = new THREE.Mesh(fg, flat(COL.foam));
  fm.position.set(0, y, z);
  scene.add(fm);

  swells.push({mesh:m, foam:fm, phase, baseY:y, z});
}

